{"command": "python3 -c "
import ast, sys
sys.path.insert(0, '.claude/skills/ascendc-translator/scripts')
from validate_ascendc_impl import ALLOWED_TORCH_FUNCS, FORBIDDEN_TENSOR_METHODS, find_model_forward, _resolve_call_name
sys.path.pop(0)

filepath = 'cann/baseline_runs/19_AvgPool3DGrad/model_new_tilelang.py'
with open(filepath) as f:
    tree = ast.parse(f.read())

forward_node = find_model_forward(tree)
if forward_node is None:
    print('ERROR: No forward() method found')
    sys.exit(1)

torch_calls = []
for node in ast.walk(forward_node):
    if isinstance(node, ast.Call):
        name = _resolve_call_name(node)
        if name:
            root = name.split('.')[0]
            if root in ('torch', 'F', 'nn', 'functional'):
                torch_calls.append(name)

if torch_calls:
    print(f'FOUND torch calls: {torch_calls}')
else:
    print('PASS: No torch compute calls in forward()')

# Check for loops
for node in ast.walk(forward_node):
    if isinstance(node, (ast.For, ast.While)):
        print(f'FOUND loop at line {node.lineno}')
" 2>&1", "description": "Manual degradation check for model_new_tilelang.py"}

