22	template <typename Derived>
23	class AvgPool3DKernelBase {
24	public:
25	    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y, GM_ADDR tilingGM, AscendC::TPipe *pipe)
26	    {
27	        CopyTiling(&tiling_, tilingGM);
28	        InitCore(x, y, pipe, tiling_.vectorLen);
29	    }
30	
31	    __aicore__ inline void Process()
32	    {
33	        if ASCEND_IS_AIV {
34	            const int workerId = static_cast<int>(AscendC::GetBlockIdx());
35	            int workerCount = tiling_.launchBlocks;
36	            if (workerCount <= 0) {
37	                workerCount = 1;
38	            }
39	            const int totalRows = tiling_.N * tiling_.outSpatial;
40	            for (int outRow = workerId; outRow < totalRows; outRow += workerCount) {
41	                ProcessOneRow(outRow);
42	            }
43	        }
44	    }
45	
46	    __aicore__ inline void InitAccumulator(int cLen)
47	    {
48	        accLocal_ = accBuf_.Get<float>();
49	        AscendC::Duplicate(accLocal_, 0.0f, cLen);
50	    }
51	
52	    __aicore__ inline void AccumulateOne(int inRow, int cBase, int cLen)
53	    {
54	        inQueue_.AllocTensor<float>(inLocal_);
55	        AscendC::DataCopy(inLocal_, xGM_[static_cast<uint64_t>(inRow) * tiling_.C + cBase], cLen);
56	        inQueue_.EnQue(inLocal_);
57	        inQueue_.DeQue<float>(inLocal_);
58	        AscendC::Add(accLocal_, accLocal_, inLocal_, cLen);
59	        inQueue_.FreeTensor(inLocal_);
60	    }
61	
62	    __aicore__ inline void AccumulateKW(int nIdx, int idVal, int ihVal, int ow, int cBase, int cLen,
63	                                         int wTile = -1, int kwGroups = -1)
64	    {
65	        if (wTile < 0) {
66	            wTile = tiling_.kW;
67	        }
68	        if (kwGroups < 0) {
69	            kwGroups = static_cast<int>(CeilDivU32(static_cast<uint32_t>(tiling_.kW), static_cast<uint32_t>(wTile)));
70	        }
71	        for (int kwBase = 0; kwBase < kwGroups; ++kwBase) {
72	            for (int kwLocal = 0; kwLocal < wTile; ++kwLocal) {
73	                const int kw = kwBase * wTile + kwLocal;
74	                if (kw >= tiling_.kW) {
75	                    continue;
76	                }
77	                const int iwVal = ow * tiling_.sW - tiling_.pW + kw;
78	                if (iwVal < 0 || iwVal >= tiling_.W) {
79	                    continue;
80	                }
81	                const int inRow = nIdx * tiling_.inSpatial + idVal * tiling_.hw + ihVal * tiling_.W + iwVal;
82	                AccumulateOne(inRow, cBase, cLen);
83	            }
84	        }
85	    }
86	
87	    __aicore__ inline void PoolKdKhLoop(int nIdx, int od, int oh, int ow, int cBase, int cLen,
88	                                        int wTile = -1, int kwGroups = -1)
89	    {
90	        for (int kd = 0; kd < tiling_.kD; ++kd) {
91	            const int idVal = od * tiling_.sD - tiling_.pD + kd;
92	            if (idVal < 0 || idVal >= tiling_.D) {
93	                continue;
94	            }
95	            for (int kh = 0; kh < tiling_.kH; ++kh) {
96	                const int ihVal = oh * tiling_.sH - tiling_.pH + kh;
97	                if (ihVal < 0 || ihVal >= tiling_.H) {
98	                    continue;
99	                }
100	                AccumulateKW(nIdx, idVal, ihVal, ow, cBase, cLen, wTile, kwGroups);
101	            }
102	        }
103	    }
104	
105	    __aicore__ inline void ProcessOneRowChunk(int nIdx, int od, int oh, int ow, int outRow, int cBase, int cLen)
106	    {
107	        InitAccumulator(cLen);
108	        PoolKdKhLoop(nIdx, od, oh, ow, cBase, cLen);
109	        AvgPool3DStoreOutput(outQueue_, outLocal_, accLocal_, yGM_,
110	                              outRow, cBase, cLen, od, oh, ow, tiling_);
111	    }
112	
113	    __aicore__ inline void ProcessOneRow(int outRow)
114	    {
115	        const int nIdx = outRow / tiling_.outSpatial;
116	        const int outRem = outRow - nIdx * tiling_.outSpatial;
117	        const int od = outRem / (tiling_.OH * tiling_.OW);
118	        const int odRem = outRem - od * (tiling_.OH * tiling_.OW);
119	        const int oh = odRem / tiling_.OW;
120	        const int ow = odRem - oh * tiling_.OW;
121	
122	        for (int cBase = 0; cBase < tiling_.C; cBase += vecLen_) {
123	            const int remain = tiling_.C - cBase;
124	            const int cLen = remain < vecLen_ ? remain : vecLen_;
125	            static_cast<Derived *>(this)->ProcessOneRowChunk(nIdx, od, oh, ow, outRow, cBase, cLen);
126	        }
127	    }
128	
129	protected:
130	    __aicore__ inline void InitCore(GM_ADDR x, GM_ADDR y, AscendC::TPipe *pipe, int vectorLen)
131	    {
132	        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(x), static_cast<uint64_t>(tiling_.N) * tiling_.inSpatial * tiling_.C);
133	        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ float *>(y), static_cast<uint64_t>(tiling_.N) * tiling_.outSpatial * tiling_.C);
134	
135	        if ASCEND_IS_AIV {
136	            pipe_ = pipe;
137	            vecLen_ = vectorLen > 0 ? vectorLen : tiling_.C;
138	            if (vecLen_ > tiling_.C) {
139	                vecLen_ = tiling_.C;
140	            }
141	
142	            pipe_->InitBuffer(inQueue_, 1, static_cast<uint32_t>(vecLen_ * sizeof(float)));
143	            pipe_->InitBuffer(outQueue_, 1, static_cast<uint32_t>(vecLen_ * sizeof(float)));
144	            pipe_->InitBuffer(accBuf_, static_cast<uint32_t>(vecLen_ * sizeof(float)));
145	        }
146	    }
147	
148	    __aicore__ inline int ComputeDivisor(int od, int oh, int ow) const
149	    {
150	        return ComputeDivisorHelper(od, oh, ow, tiling_);
151	    }
152	
153	protected:
154	    AvgPool3DKernelTiling tiling_{};
155	    AscendC::TPipe *pipe_{nullptr};
156	    int vecLen_{0};
157	
158	    AscendC::GlobalTensor<float> xGM_;
159	    AscendC::GlobalTensor<float> yGM_;
160	
161	    AscendC::TQue<AscendC::TPosition::VECIN, 0> inQueue_;
162	    AscendC::TQue<AscendC::TPosition::VECOUT, 0> outQueue_;
163	    AscendC::TBuf<AscendC::TPosition::VECCALC> accBuf_;
164	
165	    AscendC::LocalTensor<float> inLocal_;
166	    AscendC::LocalTensor<float> outLocal_;
167	    AscendC::LocalTensor<float> accLocal_;
168	};
