20	__aicore__ inline uint32_t CeilDivU32(uint32_t a, uint32_t b)
21	{
22	    if (b == 0U) { return 0U; }
23	    return (a + b - 1U) / b;
24	}
25	
26	template <typename T>
27	__aicore__ inline void CopyTiling(T *tiling, GM_ADDR tilingGM)
28	{
29	    int32_t *dst = reinterpret_cast<int32_t *>(tiling);
30	    auto *src = reinterpret_cast<__gm__ int32_t *>(tilingGM);
31	    for (size_t i = 0; i < sizeof(T) / sizeof(int32_t); ++i) {
32	        dst[i] = src[i];
33	    }
34	}
35	
36	// Shared across all AvgPool3D kernel variants (split_c, split_w, reduce_d,
37	// generic, multi_w). Computes the effective pooling divisor for the given
38	// output position, accounting for padding and countIncludePad/divisorOverride.
39	__aicore__ inline int ComputeDivisorHelper(int od, int oh, int ow,
40	                                            const AvgPool3DKernelTiling &tiling)
41	{
42	    if (tiling.divisorOverride > 0) {
43	        return tiling.divisorOverride;
44	    }
45	    if (tiling.countIncludePad > 0) {
46	        return tiling.kD * tiling.kH * tiling.kW;
47	    }
48	
49	    const int dStart = od * tiling.sD - tiling.pD;
50	    const int hStart = oh * tiling.sH - tiling.pH;
51	    const int wStart = ow * tiling.sW - tiling.pW;
52	
53	    const int dBegin = dStart < 0 ? 0 : dStart;
54	    const int hBegin = hStart < 0 ? 0 : hStart;
55	    const int wBegin = wStart < 0 ? 0 : wStart;
56	
57	    int dEnd = dStart + tiling.kD;
58	    int hEnd = hStart + tiling.kH;
59	    int wEnd = wStart + tiling.kW;
60	
61	    if (dEnd > tiling.D) { dEnd = tiling.D; }
62	    if (hEnd > tiling.H) { hEnd = tiling.H; }
63	    if (wEnd > tiling.W) { wEnd = tiling.W; }
64	
65	    const int validD = dEnd > dBegin ? (dEnd - dBegin) : 0;
66	    const int validH = hEnd > hBegin ? (hEnd - hBegin) : 0;
67	    const int validW = wEnd > wBegin ? (wEnd - wBegin) : 0;
68	    return validD * validH * validW;
69	}
70	
71	// Shared worker-loop helper — replaces the identical Process() body in AvgPool3DSplitCKernel
72	// and AvgPool3DSplitWKernel (see "duplicate code" notes in those files).
73	template <typename F>
74	__aicore__ inline void AvgPool3DProcessLoop(F &&processRowFn, int launchBlocks, int N, int outSpatial)
75	{
76	    if ASCEND_IS_AIV {
77	        const int workerId = static_cast<int>(AscendC::GetBlockIdx());
78	        int workerCount = launchBlocks;
79	        if (workerCount <= 0) {
80	            workerCount = 1;
81	        }
82	        const int totalRows = N * outSpatial;
83	        for (int outRow = workerId; outRow < totalRows; outRow += workerCount) {
84	            processRowFn(outRow);
85	        }
86	    }
87	}
88	
89	// Shared output-store helper — replaces the identical accumulator-to-GM output section in
90	// AvgPool3DSplitCKernel::ProcessOneRowChunk and AvgPool3DSplitWKernel::ProcessOneRowChunk.
91	__aicore__ inline void AvgPool3DStoreOutput(
92	    AscendC::TQue<AscendC::TPosition::VECOUT, 0> &outQueue,
93	    AscendC::LocalTensor<float> &outLocal,
94	    AscendC::LocalTensor<float> &accLocal,
95	    const AscendC::GlobalTensor<float> &yGM,
96	    int outRow, int cBase, int cLen,
97	    int od, int oh, int ow,
98	    const AvgPool3DKernelTiling &tiling)
99	{
100	    outQueue.AllocTensor<float>(outLocal);
101	    const int divisor = ComputeDivisorHelper(od, oh, ow, tiling);
102	    if (divisor <= 0) {
103	        AscendC::Duplicate(outLocal, 0.0f, cLen);
104	    } else {
105	        const float invDiv = 1.0f / static_cast<float>(divisor);
106	        AscendC::Muls(outLocal, accLocal, invDiv, cLen);
107	    }
108	    outQueue.EnQue(outLocal);
109	    outQueue.DeQue<float>(outLocal);
110	    AscendC::DataCopy(yGM[static_cast<uint64_t>(outRow) * tiling.C + cBase], outLocal, cLen);
111	    outQueue.FreeTensor(outLocal);
112	}
113	
114	#endif
