44	int64_t CeilDiv(int64_t value, int64_t factor)
45	{
46	    if (factor == 0) {
47	        return 0;
48	    }
49	    if (value % factor == 0) {
50	        return value / factor;
51	    }
52	    return value / factor + 1;
53	}
