139	static Pool3dParams NormalizePool3dParams(at::IntArrayRef kernel_size, at::IntArrayRef stride,
140	                                          at::IntArrayRef padding)
141	{
142	    Pool3dParams p;
143	    p.k_d = kernel_size[0];
144	    p.k_h = kernel_size.size() == 1 ? p.k_d : kernel_size[1];
145	    p.k_w = kernel_size.size() == 1 ? p.k_d : kernel_size[2];
146	
147	    p.s_d = stride.empty() ? p.k_d : stride[0];
148	    p.s_h = stride.empty() ? p.k_h : (stride.size() == 1 ? p.s_d : stride[1]);
149	    p.s_w = stride.empty() ? p.k_w : (stride.size() == 1 ? p.s_d : stride[2]);
150	
151	    p.p_d = padding[0];
152	    p.p_h = padding.size() == 1 ? p.p_d : padding[1];
153	    p.p_w = padding.size() == 1 ? p.p_d : padding[2];
154	
155	    return p;
156	}
