298	at::Tensor avg_pool3d(const at::Tensor &self, at::IntArrayRef kernel_size, at::IntArrayRef stride,
299	                      at::IntArrayRef padding, bool ceil_mode, bool count_include_pad,
300	                      c10::optional<int64_t> divisor_override)
301	{
302	    TORCH_CHECK(self.dim() == 4 || self.dim() == 5, "avg_pool3d: input must be 4D or 5D");
303	    TORCH_CHECK(!kernel_size.empty(), "avg_pool3d: kernel_size must not be empty");
304	
305	    auto params = NormalizePool3dParams(kernel_size, stride, padding);
306	    int64_t k_d = params.k_d, k_h = params.k_h, k_w = params.k_w;
307	    int64_t s_d = params.s_d, s_h = params.s_h, s_w = params.s_w;
308	    int64_t p_d = params.p_d, p_h = params.p_h, p_w = params.p_w;
309	
310	    TORCH_CHECK(s_d != 0 && s_h != 0 && s_w != 0, "avg_pool3d: stride should not contain zero");
311	
312	    c10::SmallVector<int64_t, 3> kernel_sizes = {k_d, k_h, k_w};
313	    c10::SmallVector<int64_t, 3> stride_sizes = {s_d, s_h, s_w};
314	    c10::SmallVector<int64_t, 3> padding_sizes = {p_d, p_h, p_w};
315	
316	    auto output_size = avg_pool3d_output_size(self, at::IntArrayRef(kernel_sizes),
317	                                               at::IntArrayRef(stride_sizes),
318	                                               at::IntArrayRef(padding_sizes), ceil_mode);
319	    at::Tensor result = at_npu::native::empty_with_format(
320	        output_size, self.options(), at_npu::native::get_npu_format(self));
321	
322	    int64_t n = self.size(0);
323	    bool is_5d = (self.dim() == 5);
324	    int64_t c = is_5d ? self.size(1) : 1;
325	    int64_t d = self.size(-3), h = self.size(-2), w = self.size(-1);
326	    int64_t dim_offset = is_5d ? 1 : 0;
327	    int64_t o_d = output_size[1 + dim_offset];
328	    int64_t o_h = output_size[2 + dim_offset];
329	    int64_t o_w = output_size[3 + dim_offset];
330	
331	    at::Tensor y_flat = PrepareAndLaunchAvgPool3d(
332	        self, is_5d, n, c, d, h, w, o_d, o_h, o_w,
333	        k_d, k_h, k_w, s_d, s_h, s_w, p_d, p_h, p_w,
334	        count_include_pad, divisor_override);
335	
336	    at::Tensor y_ndhwc = y_flat.reshape({n, o_d, o_h, o_w, c});
337	    at::Tensor y_ncdhw = y_ndhwc.permute({0, 4, 1, 2, 3}).contiguous();
338	    if (self.dim() == 4) {
339	        y_ncdhw = y_ncdhw.squeeze(1).contiguous();
340	    }
341	    if (!y_ncdhw.is_same(result)) {
342	        result.copy_(y_ncdhw);
343	    }
344	    return result;
345	}
