class AvgPool3DGradKernel {
public:
    __aicore__ inline void Init(GM_ADDR gradOut, GM_ADDR gradIn, GM_ADDR tilingGM, AscendC::TPipe *pipe)
    {
        CopyTilingGrad(&tiling_, tilingGM);
        InitCore(gradOut, gradIn, pipe, tiling_.vectorLen);
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            const int workerId = static_cast<int>(AscendC::GetBlockIdx());
            int workerCount = tiling_.launchBlocks;
            if (workerCount <= 0) {
                workerCount = 1;
            }
            const int totalRows = tiling_.N * tiling_.inSpatial;
            for (int inRow = workerId; inRow < totalRows; inRow += workerCount) {
                ProcessOneInputRow(inRow);
            }
        }
    }

private:
    __aicore__ inline void InitCore(GM_ADDR gradOut, GM_ADDR gradIn, AscendC::TPipe *pipe, int vectorLen)
    {
        gradOutGM_.SetGlobalBuffer(
            reinterpret_cast<__gm__ float *>(gradOut),
            static_cast<uint64_t>(tiling_.N) * tiling_.outSpatial * tiling_.C);
        gradInGM_.SetGlobalBuffer(
            reinterpret_cast<__gm__ float *>(gradIn),
            static_cast<uint64_t>(tiling_.N) * tiling_.inSpatial * tiling_.C);

        if ASCEND_IS_AIV {
            pipe_ = pipe;
            vecLen_ = vectorLen > 0 ? vectorLen : tiling_.C;
            if (vecLen_ > tiling_.C) {
                vecLen_ = tiling_.C;
            }

            pipe_->InitBuffer(inQueue_, 1, static_cast<uint32_t>(vecLen_ * sizeof(float)));
            pipe_->InitBuffer(outQueue_, 1, static_cast<uint32_t>(vecLen_ * sizeof(float)));
            pipe_->InitBuffer(accBuf_, static_cast<uint32_t>(vecLen_ * sizeof(float)));
        }
    }

    __aicore__ inline void InitAccumulator(int cLen)
    {
        accLocal_ = accBuf_.Get<float>();
        AscendC::Duplicate(accLocal_, 0.0f, cLen);
    }

    __aicore__ inline void AccumulateFromOutput(int outRow, int cBase, int cLen, float invDivisor)
    {
        inQueue_.AllocTensor<float>(inLocal_);
        AscendC::DataCopy(
            inLocal_,
            gradOutGM_[static_cast<uint64_t>(outRow) * tiling_.C + cBase],
            cLen);
        inQueue_.EnQue(inLocal_);
        inQueue_.DeQue<float>(inLocal_);
        // acc += grad_out * invDivisor
        AscendC::Axpy(accLocal_, inLocal_, invDivisor, cLen);
        inQueue_.FreeTensor(inLocal_);
    }

    __aicore__ inline void ProcessOutputWindowW(
        int nIdx, int idVal, int ihVal, int owMin, int owMax, int cBase, int cLen)
    {
        for (int ow = owMin; ow <= owMax; ++ow) {
            int divisor = ComputeGradDivisorHelper(
                /* dummy od/oh for w-only */ 0, 0, ow, tiling_);
            // We need the full (od, oh, ow) for proper divisor computation.
            // This placeholder is filled in the D-H loop below.
            (void)nIdx; (void)idVal; (void)ihVal;
            (void)cBase; (void)cLen; (void)divisor;
        }
    }

    __aicore__ inline void AccumulateOutputElement(
        int nIdx, int od, int oh, int ow, int cBase, int cLen)
    {
        int divisor = ComputeGradDivisorHelper(od, oh, ow, tiling_);
        if (divisor <= 0) {
            return;
        }
        float invDivisor = 1.0f / static_cast<float>(divisor);
        int outRow = nIdx * tiling_.outSpatial + od * tiling_.outHw + oh * tiling_.OW + ow;
        AccumulateFromOutput(outRow, cBase, cLen, invDivisor);
    }

    __aicore__ inline void ProcessOutputWindowWRange(
        int nIdx, int od, int oh, int owMin, int owMax, int cBase, int cLen)
    {
        for (int ow = owMin; ow <= owMax; ++ow) {
            AccumulateOutputElement(nIdx, od, oh, ow, cBase, cLen);
        }
    }

    __aicore__ inline void ProcessOutputWindowHRange(
        int nIdx, int idVal, int ihMin, int ihMax, int owMin, int owMax,
        int cBase, int cLen)
    {
        (void)idVal;
        // For each oh in [ohMin, ohMax], find corresponding od range by the same formula
        // Actually, od and oh ranges are independent for the backward pass.
        // We need to iterate over all (od, oh, ow) triples.
        // This function iterates over oh range.
        for (int oh = ihMin; oh <= ihMax; ++oh) {
            ProcessOutputWindowWRange(nIdx, /* dummy od */ 0, oh, owMin, owMax, cBase, cLen);
        }
    }

    __aicore__ inline void ProcessOutputWindowFull(
        int nIdx, int odMin, int odMax, int ohMin, int ohMax, int owMin, int owMax,
        int cBase, int cLen)
    {
        for (int od = odMin; od <= odMax; ++od) {
            for (int oh = ohMin; oh <= ohMax; ++oh) {
                for (int ow = owMin; ow <= owMax; ++ow) {
                    AccumulateOutputElement(nIdx, od, oh, ow, cBase, cLen);
                }
            }
        }
    }

    __aicore__ inline void ProcessOneInputRow(int inRow)
    {
        // Decompose flattened input row into (n, id, ih, iw)
        const int nIdx = inRow / tiling_.inSpatial;
        const int inRem = inRow - nIdx * tiling_.inSpatial;
        const int idVal = inRem / tiling_.hw;
        const int hwRem = inRem - idVal * tiling_.hw;
        const int ihVal = hwRem / tiling_.W;
        const int iwVal = hwRem - ihVal * tiling_.W;

        // Compute output window bounds for this input position.
        // For the backward pass, an input at (id, ih, iw) receives gradients from
        // output positions whose pooling windows include this input.
        //
        // od satisfies: od*stride_d - pad_d <= id < od*stride_d - pad_d + kernel_d
        // => od_min = max(0, (id + pad_d - kernel_d + stride_d) // stride_d)
        //    od_max = min(out_d - 1, (id + pad_d) // stride_d)
        const int odMinRaw = (idVal + tiling_.pD - tiling_.kD + tiling_.sD) / tiling_.sD;
        const int odMin = odMinRaw < 0 ? 0 : odMinRaw;
        const int odMaxRaw = (idVal + tiling_.pD) / tiling_.sD;
        const int odMax = odMaxRaw >= tiling_.OD ? (tiling_.OD - 1) : odMaxRaw;

        const int ohMinRaw = (ihVal + tiling_.pH - tiling_.kH + tiling_.sH) / tiling_.sH;
        const int ohMin = ohMinRaw < 0 ? 0 : ohMinRaw;
        const int ohMaxRaw = (ihVal + tiling_.pH) / tiling_.sH;
        const int ohMax = ohMaxRaw >= tiling_.OH ? (tiling_.OH - 1) : ohMaxRaw;

        const int owMinRaw = (iwVal + tiling_.pW - tiling_.kW + tiling_.sW) / tiling_.sW;
        const int owMin = owMinRaw < 0 ? 0 : owMinRaw;
        const int owMaxRaw = (iwVal + tiling_.pW) / tiling_.sW;
        const int owMax = owMaxRaw >= tiling_.OW ? (tiling_.OW - 1) : owMaxRaw;

        // If the window is empty, output is zero
        if (odMin > odMax || ohMin > ohMax || owMin > owMax) {
            // Write zeros to gradIn
            for (int cBase = 0; cBase < tiling_.C; cBase += vecLen_) {
                const int remain = tiling_.C - cBase;
                const int cLen = remain < vecLen_ ? remain : vecLen_;
                outQueue_.AllocTensor<float>(outLocal_);
                AscendC::Duplicate(outLocal_, 0.0f, cLen);
                outQueue_.EnQue(outLocal_);
                outQueue_.DeQue<float>(outLocal_);
                AscendC::DataCopy(
                    gradInGM_[static_cast<uint64_t>(inRow) * tiling_.C + cBase],
                    outLocal_, cLen);
                outQueue_.FreeTensor(outLocal_);
            }
            return;
        }

        // Process channel dimension in chunks
        for (int cBase = 0; cBase < tiling_.C; cBase += vecLen_) {
            const int remain = tiling_.C - cBase;
            const int cLen = remain < vecLen_ ? remain : vecLen_;

            // Initialize accumulator
            InitAccumulator(cLen);

            // Accumulate from output window
            ProcessOutputWindowFull(nIdx, odMin, odMax, ohMin, ohMax, owMin, owMax,
                                    cBase, cLen);

            // Write result to gradIn
            outQueue_.AllocTensor<float>(outLocal_);
            AscendC::DataCopy(outLocal_, accLocal_, cLen);
            outQueue_.EnQue(outLocal_);
            outQueue_.DeQue<float>(outLocal_);
            AscendC::DataCopy(
                gradInGM_[static_cast<uint64_t>(inRow) * tiling_.C + cBase],
                outLocal_, cLen);
            outQueue_.FreeTensor(outLocal_);
        }
    }

private:
    AvgPool3DGradKernelTiling tiling_{};
    AscendC::TPipe *pipe_{nullptr};
    int vecLen_{0};

    AscendC::GlobalTensor<float> gradOutGM_;
    AscendC::GlobalTensor<float> gradInGM_;

    AscendC::TQue<AscendC::TPosition::VECIN, 0> inQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, 0> outQueue_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> accBuf_;

    AscendC::LocalTensor<float> inLocal_;
    AscendC::LocalTensor<float> outLocal_;
    AscendC::LocalTensor<float> accLocal_;
};

extern "C" __global__ __aicore__ void avg_pool3d_grad(GM_ADDR gradOut, GM_ADDR gradIn, GM_ADDR tiling)
{
    KERNEL_TASK_TYPE_DEFAULT(KERNEL_TYPE_MIX_AIC_1_2);
    AscendC::TPipe pipe;
    AvgPool3DGradKernel kernel;
    kernel.Init(gradOut, gradIn, tiling, &pipe);
    kernel.Process();
}
