#include "avg_pool3d_grad_tiling.h"
#include "aclrtlaunch_avg_pool3d_grad.h"

namespace ascend_kernel {

namespace {

inline int32_t CeilDivI32(int32_t a, int32_t b)
{
    if (b == 0) { return 0; }
    return (a + b - 1) / b;
}

int32_t ChooseBlockM(int32_t mIn)
{
    for (int32_t candidate : {64, 32, 16, 8, 4, 2}) {
        if (candidate <= mIn && mIn % candidate == 0) {
            return candidate;
        }
    }
    TORCH_CHECK(false, "Unsupported input spatial size: M_in=", mIn);
    return 0;
}

static inline void PopulateAvgPool3dGradTiling(
    AvgPool3DGradKernelTiling *tiling,
    int32_t n32, int32_t c32, int32_t d32, int32_t h32, int32_t w32,
    int32_t od32, int32_t oh32, int32_t ow32,
    int32_t kd32, int32_t kh32, int32_t kw32,
    int32_t sd32, int32_t sh32, int32_t sw32,
    int32_t pd32, int32_t ph32, int32_t pw32,
    int32_t countIncludePad, int32_t divisorOverride,
    int32_t blockM, int32_t subBlockM, int32_t mNum,
    int32_t outSpatial, int32_t inSpatial,
    int32_t usedCoreNum, int32_t tasksPerCore,
    int32_t vectorLen)
{
    tiling->N = n32;
    tiling->C = c32;
    tiling->D = d32;
    tiling->H = h32;
    tiling->W = w32;
    tiling->OD = od32;
    tiling->OH = oh32;
    tiling->OW = ow32;
    tiling->kD = kd32;
    tiling->kH = kh32;
    tiling->kW = kw32;
    tiling->sD = sd32;
    tiling->sH = sh32;
    tiling->sW = sw32;
    tiling->pD = pd32;
    tiling->pH = ph32;
    tiling->pW = pw32;
    tiling->countIncludePad = countIncludePad;
    tiling->divisorOverride = divisorOverride;
    tiling->blockM = blockM;
    tiling->subBlockM = subBlockM;
    tiling->mNum = mNum;
    tiling->outSpatial = outSpatial;
    tiling->inSpatial = inSpatial;
    tiling->hw = h32 * w32;
    tiling->outHw = oh32 * ow32;
    tiling->usedCoreNum = usedCoreNum;
    tiling->tasksPerCore = tasksPerCore;
    tiling->vectorLen = vectorLen;
    tiling->reserved0 = 0;
    tiling->reserved1 = 0;
}

int64_t CeilDiv(int64_t value, int64_t factor)
{
    if (factor == 0) { return 0; }
    return (value + factor - 1) / factor;
}

} // namespace

at::Tensor avg_pool3d_grad(
    const at::Tensor &grad_output,
    const at::Tensor &x,
    at::IntArrayRef kernel_size,
    at::IntArrayRef stride,
    at::IntArrayRef padding,
    bool ceil_mode,
    bool count_include_pad,
    int64_t divisor_override)
{
    TORCH_CHECK(x.dim() == 5, "avg_pool3d_grad: x must be 5D (NCDHW)");
    TORCH_CHECK(grad_output.dim() == 5, "avg_pool3d_grad: grad_output must be 5D (NCDHW)");

    int64_t n = x.size(0);
    int64_t c = x.size(1);
    int64_t d = x.size(2);
    int64_t h = x.size(3);
    int64_t w = x.size(4);

    int64_t k_d = kernel_size[0];
    int64_t k_h = kernel_size.size() > 1 ? kernel_size[1] : k_d;
    int64_t k_w = kernel_size.size() > 2 ? kernel_size[2] : k_d;

    int64_t s_d = stride.empty() ? k_d : stride[0];
    int64_t s_h = stride.empty() ? k_h : (stride.size() > 1 ? stride[1] : s_d);
    int64_t s_w = stride.empty() ? k_w : (stride.size() > 2 ? stride[2] : s_w);

    int64_t p_d = padding[0];
    int64_t p_h = padding.size() > 1 ? padding[1] : p_d;
    int64_t p_w = padding.size() > 2 ? padding[2] : p_d;

    // Compute output spatial dimensions
    int64_t o_d, o_h, o_w;
    if (!ceil_mode) {
        o_d = (d + 2 * p_d - k_d) / s_d + 1;
        o_h = (h + 2 * p_h - k_h) / s_h + 1;
        o_w = (w + 2 * p_w - k_w) / s_w + 1;
    } else {
        o_d = CeilDiv(d + 2 * p_d - k_d, s_d) + 1;
        o_h = CeilDiv(h + 2 * p_h - k_h, s_h) + 1;
        o_w = CeilDiv(w + 2 * p_w - k_w, s_w) + 1;
        if ((o_d - 1) * s_d >= d + p_d) { --o_d; }
        if ((o_h - 1) * s_h >= h + p_h) { --o_h; }
        if ((o_w - 1) * s_w >= w + p_w) { --o_w; }
    }

    // Convert to int32 for tiling
    int32_t n32 = static_cast<int32_t>(n);
    int32_t c32 = static_cast<int32_t>(c);
    int32_t d32 = static_cast<int32_t>(d);
    int32_t h32 = static_cast<int32_t>(h);
    int32_t w32 = static_cast<int32_t>(w);
    int32_t od32 = static_cast<int32_t>(o_d);
    int32_t oh32 = static_cast<int32_t>(o_h);
    int32_t ow32 = static_cast<int32_t>(o_w);
