    at::Tensor go_ndhwc = grad_output.permute({0, 2, 3, 4, 1}).contiguous();
    at::Tensor go_flat = go_ndhwc.reshape({n * o_d * o_h * o_w, c}).to(at::kFloat);
    TORCH_CHECK(go_flat.is_contiguous(), "avg_pool3d_grad: go_flat must be contiguous");

    // Compute tiling parameters
    int32_t inSpatial = d32 * h32 * w32;
    int32_t outSpatial = od32 * oh32 * ow32;
    int32_t mIn = n32 * inSpatial;
    int32_t blockM = ChooseBlockM(mIn);
    if (blockM == 0) { blockM = 1; }
    int32_t subBlockM = blockM / 2;  // vec_num = 2
    int32_t mNum = mIn / blockM;
    int32_t usedCoreNum = std::min(20, mNum);
    int32_t tasksPerCore = CeilDivI32(mNum, usedCoreNum);
    int32_t vectorLen = std::min<int32_t>(c32, 256);

