    at::Tensor gi_flat = at::empty({mIn, c32}, at::device(at::kPrivateUse1).dtype(at::kFloat));

    // Create tiling tensor
    at::Tensor tilingCpu = at::empty(
        {static_cast<int64_t>(sizeof(AvgPool3DGradKernelTiling))},
        at::device(at::kCPU).dtype(at::kByte));
    auto *tiling = reinterpret_cast<AvgPool3DGradKernelTiling *>(tilingCpu.data_ptr());

    PopulateAvgPool3dGradTiling(
        tiling,
        n32, c32, d32, h32, w32, od32, oh32, ow32,
        kd32, kh32, kw32, sd32, sh32, sw32, pd32, ph32, pw32,
        count_include_pad ? 1 : 0, static_cast<int32_t>(divisor_override),
        blockM, subBlockM, mNum, outSpatial, inSpatial,
        usedCoreNum, tasksPerCore, vectorLen);

    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);
    tiling->launchBlocks = static_cast<int32_t>(blockDim);
    auto tilingNpu = tilingCpu.to(at::kPrivateUse1);

    EXEC_KERNEL_CMD(avg_pool3d_grad, blockDim, go_flat, gi_flat, tilingNpu);

    // Reshape back to NCDHW
    at::Tensor gi_ndhwc = gi_flat.reshape({n, d, h, w, c});
    at::Tensor gi_ncdhw = gi_ndhwc.permute({0, 4, 1, 2, 3}).contiguous();

    return gi_ncdhw;
}

