        const int owMinRaw = (iwVal + tiling_.pW - tiling_.kW + tiling_.sW) / tiling_.sW;
        const int owMin = owMinRaw < 0 ? 0 : owMinRaw;
        const int owMaxRaw = (iwVal + tiling_.pW) / tiling_.sW;
        const int owMax = owMaxRaw >= tiling_.OW ? (tiling_.OW - 1) : owMaxRaw;

